'use strict';
const $=id=>document.getElementById(id),KEY='co-chill-v4-browser',NAMES={k:'Tướng',a:'Sĩ',e:'Tượng',r:'Xe',h:'Mã',c:'Pháo',p:'Tốt'},HAN={K:'帥',A:'仕',E:'相',R:'俥',H:'傌',C:'炮',P:'兵',k:'將',a:'士',e:'象',r:'車',h:'馬',c:'砲',p:'卒'};
const SKILLS={material:'Quan sát và bảo vệ quân',cannon:'Đường Pháo và quân ngòi',horse:'Đường Mã và chân Mã',safety:'An toàn của Tướng'};
const HOW={material:'Kiểm tra an toàn Tướng, tìm nước ăn quân, rồi xem đối thủ có ăn lại được không.',cannon:'Đếm đúng một quân ngòi khi Pháo ăn quân. Kiểm tra lại đường Pháo sau mỗi nước.',horse:'Xác định chân Mã trước khi tính ô đích. Xét cả đường tiến và đường lui.',safety:'Khi bị chiếu, xét di chuyển Tướng, bắt quân chiếu hoặc che đường chiếu hợp lệ.'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v).toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'Chưa hẹn';
const btn=(text,action,value='',cls='primary')=>`<button class="${cls}" data-action="${action}" data-value="${esc(value)}">${text}</button>`;
let state=CC.fresh(),storageOK=true,selected=null,mode='bot',lessonPhase='middle',showMarks=true,replayIndex=0,busy=false,toastTimer;
const PREF_KEY='co-chill-preferences-v1';
let prefs=CC.preferences(),boardFlipped=false,showVariation=false,libraryPage=0,libraryFilter='all',analysisProgress='',audioContext,previousRoute=location.hash||'#home';
try{prefs=CC.preferences(JSON.parse(localStorage.getItem(PREF_KEY)||'null'));}catch{}
try{state=CC.sanitize(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}if(!storageOK){$('storage-warning').hidden=false;$('storage-warning').textContent='Trình duyệt không lưu được dữ liệu. Phiên này chỉ giữ khi trang còn mở; hãy xuất dữ liệu trước khi đóng.';}}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,7000);}
function go(route){if(location.hash==='#'+route)render();else{internalNavigation=true;location.hash=route;}}
function route(){return(location.hash.slice(1)||'home').split('/');}
function activeGame(){return state.games.find(g=>g.status&&!g.status.over);}
function findPuzzle(id){return FIXTURES.find(p=>p.id===id)||state.games.flatMap(g=>g.moments||[]).find(p=>p.id===id)||(state.session&&state.session.puzzleId===id?state.session.puzzle:null);}
function dueRecords(){return Object.values(state.records).filter(r=>r.dueAt&&Date.parse(r.dueAt)<=Date.now());}
function completed(){return Object.values(state.records).filter(r=>r.completedAt);}
function heading(title,sub='',back='home'){return `<a class="crumb" href="#${back}">← Quay lại</a><div class="page-top"><div><h1>${title}</h1><p>${sub}</p></div><span class="pill">Bản thử nghiệm</span></div>`;}
function empty(title,copy,link='lessons',cta='Khám phá bài học'){return `<div class="panel empty"><div class="empty-mark">棋</div><h3>${title}</h3><p>${copy}</p><a class="primary" href="#${link}">${cta} →</a></div>`;}
function home(){const due=dueRecords().length,s=state.session,ongoing=s&&s.stage!=='summary';return `<section class="home-intro"><span class="status-dot">Một góc nhỏ để học cờ tướng</span><h1>Chơi một ván.<br><em>Hiểu thêm một chút.</em></h1><p>Chậm lại ở nước đi đáng nhớ. Tự tìm ý tưởng, hiểu lý do và thử sức ở một thế cờ mới.</p></section><div class="next-up"><div><strong>${ongoing?'Bài học của bạn vẫn ở đây':due?`${due} hình cờ đã đến lúc ôn`:'Bắt đầu bằng một thế cờ nhỏ'}</strong><p>${ongoing?'Câu trả lời và bước đang làm đã được giữ lại.':due?'Ôn một chút, rồi tiếp tục hành trình.':'Khoảng 3–5 phút · Không cần tài khoản'}</p></div>${ongoing?btn('Tiếp tục →','resume'):due?'<a class="primary" href="#review">Ôn hôm nay →</a>':'<a class="primary" href="#howto">Bắt đầu chơi →</a>'}</div><section class="home-grid" aria-label="Bốn khu vực chính"><a class="home-card" href="#play"><span class="tile-symbol">車</span><div><h2>Chơi cờ</h2><p>Một ván với máy, hoặc cùng một người bạn trên thiết bị này.</p><span class="tiny-badge">Máy nhẹ · Hai người</span></div><span class="tile-arrow">↗</span></a><a class="home-card" href="#lessons"><span class="tile-symbol">冊</span><div><h2>Bài học</h2><p>Từ ý tưởng khai cuộc đến cách nhìn một thế cờ.</p><span class="tiny-badge">12 hình cờ · 4 kỹ năng</span></div><span class="tile-arrow">↗</span></a><a class="home-card" href="#mistakes"><span class="tile-symbol">↶</span><div><h2>Ván của tôi</h2><p>Trở lại những khoảnh khắc đáng học từ ván của bạn.</p></div><span class="tile-arrow">↗</span></a><a class="home-card" href="#review"><span class="tile-symbol">◷</span><div><h2>Ôn tập</h2><p>Tiếp tục bài đang dở và luyện lại khi đến hẹn.</p><span class="tiny-badge">${due?due+' hình đến hạn':'Theo nhịp của bạn'}</span></div><span class="tile-arrow">↗</span></a></section><div class="home-bottom"><div class="mini-stats"><span><b>${completed().length}</b>hình đã luyện</span><span><b>${state.games.filter(g=>g.status?.over).length}</b>ván đã lưu</span><span><b>${state.summaries.length}</b>lần tự nhìn lại</span></div><p>Không có lời giải trước khi bạn suy nghĩ.<br><a href="#howto">Tìm hiểu cách học ↗</a></p></div>`;}
function boardHTML(pos,{interactive=false,chosen=null,last=null,mark=null}={}){
 let lines='';for(let y=0;y<10;y++)lines+=`<line x1="25" y1="${25+50*y}" x2="425" y2="${25+50*y}"/>`;
 for(let x=0;x<9;x++){const xx=25+50*x;lines+=`<line x1="${xx}" y1="25" x2="${xx}" y2="225"/><line x1="${xx}" y1="275" x2="${xx}" y2="475"/>`;}
 lines+='<path d="M25 225V275M425 225V275M175 25L275 125M275 25L175 125M175 375L275 475M275 375L175 475"/>';
 const screen=i=>boardFlipped?89-i:i;
 const checked=pos.inCheck();
 let html=`<div class="board-shell"><div class="board" role="group" aria-label="Bàn cờ tướng"><svg class="board-lines" viewBox="0 0 450 500" aria-hidden="true"><g stroke="currentColor" stroke-width="1.3" fill="none">${lines}</g><text x="132" y="257" text-anchor="middle" fill="currentColor" font-family="serif" font-size="19">楚 河</text><text x="322" y="257" text-anchor="middle" fill="currentColor" font-family="serif" font-size="19">漢 界</text></svg>`;
 pos.board.forEach((piece,i)=>{const sq=XQ.square(i),j=screen(i),name=piece==='.'?'Ô trống':NAMES[piece.toLowerCase()]+' '+(XQ.side(piece)==='w'?'Đỏ':'Đen');
 html+=`<button type="button" class="board-square${chosen===sq?' selected':''}${last?.slice(0,2)===sq?' last-from':''}${last?.slice(2)===sq?' last-to':''}${checked&&piece.toLowerCase()==='k'&&XQ.side(piece)===pos.turn?' checked':''}" style="left:${(j%9+.5)/9*100}%;top:${(Math.floor(j/9)+.5)/10*100}%" data-square="${sq}" aria-label="${sq} · ${name}" ${interactive?'':'disabled'}>${piece==='.'?'':`<span class="piece${XQ.side(piece)==='w'?' red':''}${prefs.pieces==='vi'?' vietnamese':''}">${prefs.pieces==='vi'?NAMES[piece.toLowerCase()]:HAN[piece]}</span>`}</button>`;});
 if(mark&&showMarks){const a=screen(XQ.index(mark.slice(0,2))),b=screen(XQ.index(mark.slice(2)));html+=`<svg class="board-overlay" viewBox="0 0 450 500" aria-hidden="true"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="5" refY="3.5" orient="auto"><path d="M0 0L7 3.5L0 7" fill="#2a705d"/></marker></defs><circle cx="${25+(a%9)*50}" cy="${25+Math.floor(a/9)*50}" r="22" fill="none" stroke="#2a705d" stroke-width="3"/><path d="M${25+(a%9)*50} ${25+Math.floor(a/9)*50}L${25+(b%9)*50} ${25+Math.floor(b/9)*50}" fill="none" stroke="#2a705d" stroke-width="4" marker-end="url(#arrow)"/></svg>`;}
 return html+`</div><div class="board-caption"><span>${boardFlipped?'Đen':'Đỏ'} ở dưới</span><span>Bấm lại quân đang chọn để bỏ chọn</span></div></div><div class="board-tools">${btn('⇅ Lật bàn','flip-board','','quiet')}${btn(prefs.pieces==='han'?'Chữ Việt':'Chữ Hán','toggle-pieces','','quiet')}</div>`;
}
function beginPuzzle(p,{related=false,source='lesson',force=false}={}){if(!p)return toast('Không tìm thấy bài.');if(activeGame())return toast('Hãy kết thúc ván đang chơi trước khi mở hướng dẫn.');if(!force&&state.session&&state.session.stage!=='summary'&&state.session.puzzleId!==p.id&&!confirm('Bạn đang có một bài dở. Bắt đầu bài mới sẽ thay chỗ tiếp tục hiện tại; kết quả đã hoàn thành vẫn giữ.'))return;state=CC.markSeen(state,p);state.session=CC.createSession(p,{source,related});selected=null;showVariation=false;save();go('learn');}
function currentPuzzle(){return findPuzzle(state.session?.puzzleId);}
function accepted(p,move){return !!move&&(move===p.solution||(p.alternatives||[]).includes(move));}
function learn(){
 const session=state.session,p=currentPuzzle();if(!session||!p)return empty('Chọn một hình cờ để bắt đầu','Mỗi bài đều bắt đầu bằng suy nghĩ của bạn.');
 if(activeGame())return empty('Ván cờ vẫn đang diễn ra','Hướng dẫn được mở sau khi ván kết thúc.','game/'+activeGame().id,'Quay lại ván');
 const pos=XQ.Position.fromFen(p.fen),after=['explain','retry','complete','summary'].includes(session.stage);let right='';
 if(session.stage==='related_pending'){
 const q=findPuzzle(session.pendingPuzzleId);right=`<p class="eyebrow">VẬN DỤNG</p><h2>Thử thêm một bài nữa.</h2><p>Phần vừa học đã được ghi lại. Hãy thử tự quan sát hình tiếp theo.</p><p class="subtle">${q&&state.records[q.id]?.seenCount?'Bài đã gặp. Kho bài hiện còn nhỏ.':'Bài chưa gặp trên trình duyệt này.'}</p>${btn('Bắt đầu bài tiếp theo →','related-start')}${btn('Để lần sau','pause','','quiet')}<p class="subtle">Bạn sẽ quay lại đúng bước này; bài tiếp theo chưa được tính là đã làm.</p>`;
 }else if(session.stage==='reflect'){
 const wait=Math.max(0,Math.ceil(((session.helpReadyAt||0)-Date.now())/1000));
 right=`<p class="eyebrow">TỰ QUAN SÁT · ${session.submissionCount?`LƯỢT ${Math.min(3,session.submissionCount+1)}/3`:'TRƯỚC LỜI GIẢI'}</p><h2>${prefs.tone==='friendly'?'Mình cùng nhìn thế cờ nhé.':'Bạn nhìn thế cờ thế nào?'}</h2><p class="subtle">Nêu ý ngắn, rồi chọn một nước trên bàn. Bản thử kiểm tra nước đi; chưa tự chấm hiểu biết qua câu chữ.</p>${session.coachFeedback?`<p class="notice">${esc(session.coachFeedback)}</p>`:''}<form id="reflection-form">${CC.PROMPTS.map((q,i)=>`<label class="field"><span class="question-label"><i>0${i+1}</i> ${q}</span><textarea data-answer="${i}" rows="2" maxlength="1500" aria-describedby="hint-${i}" placeholder="Suy nghĩ của bạn…">${esc(session.answers[i])}</textarea><span id="hint-${i}" class="question-hint">${session.helpLevel||prefs.level==='new'?CC.HINTS[i]:''}</span></label>`).join('')}<div class="candidate" id="candidate">${session.candidate?'Nước bạn chọn: '+esc(CC.notateMove(pos,session.candidate)):'Chọn quân, rồi chọn ô đến để đề xuất một nước.'}</div><div class="button-row"><button class="primary" type="submit">Gửi suy nghĩ →</button></div></form>${btn('Tôi chưa biết · giúp tôi quan sát','unknown','','quiet')}${session.helpLevel?`<div class="question-hint"><p>Hãy dành một chút thời gian quan sát theo các gợi ý trên. Bạn có thể gửi câu trả lời bất cứ lúc nào.</p><button class="secondary" data-action="guided-reveal" id="guided-reveal" ${wait?'disabled':''}>${wait?`Quan sát thêm ${wait} giây`:'Vẫn chưa tìm ra · xem hướng dẫn'}</button><p class="subtle">Xem hướng dẫn được ghi là có hỗ trợ và cần ôn lại.</p></div>`:''}`;
 }else if(session.stage==='retry'){
 right=`<p class="eyebrow">LUYỆN LẠI · SAU HƯỚNG DẪN</p><h2>Thử lại ý tưởng vừa học.</h2><p>Chọn quân và ô đến. Bạn còn ${Math.max(0,3-(session.retryCount||0))} lượt thử trong phiên này.</p>${btn('Quay về giải thích','explain','','secondary')}<p class="subtle">Thử lại sau lời giải không được tính thành tự giải lần đầu.</p>`;
 }else{
 const assisted=session.assisted||!accepted(p,session.candidate);
 right=`<p class="eyebrow">ĐỐI CHIẾU SUY NGHĨ</p><h2>Ý tưởng cần giữ lại.</h2><p class="notice">${assisted?'Lượt này có hỗ trợ hoặc cần luyện thêm. Sau đây là một phương án để bạn đối chiếu.':'Nước đề xuất phù hợp mục tiêu mẫu. Hãy đối chiếu cả lý do; hệ thống chưa tự xác nhận câu trả lời tự do đúng hoàn toàn.'}</p><div class="explanation-section"><h4>Thế cờ thay đổi như thế nào?</h4><p>${esc(p.what)}</p></div><div class="explanation-section"><h4>Điều gì làm nên ý tưởng này?</h4><p>${esc(p.why)}</p></div><div class="explanation-section"><h4>Lần tới bạn nên kiểm tra điều gì?</h4><p>${esc(p.how||HOW[p.skill])}</p></div><div class="button-row">${btn(showVariation?'↶ Trở về thế ban đầu':'Xem nước minh họa trên bàn','variation','','secondary')}${btn('Thử lại vị trí này','retry','','secondary')}</div><details class="separation"><summary>Chi tiết hơn · suy nghĩ và căn cứ</summary><p>Nước minh họa: ${esc(CC.notateMove(pos,p.solution))}. Có thể có nhiều phương án hợp lý.</p>${(session.firstAnswers||session.answers).map((a,i)=>`<p><b>Suy nghĩ ban đầu ${i+1}:</b> ${esc(a||'Chưa biết')}</p>`).join('')}<p>Lời giải theo mẫu và nước hợp lệ. Hệ thống tìm kiếm tối đa hai nửa nước; chưa có AI chấm lập luận. Không dùng điểm này làm xếp hạng.</p></details><div class="button-row">${btn(session.related?'Lưu lượt học & tự nhìn lại →':assisted?'Lưu lượt học & đưa vào ôn tập →':'Lưu lượt học & làm bài tiếp →','finish')}</div><p class="subtle">Lịch ôn tính từ lúc bạn kết thúc hình này. Hoàn thành lượt luyện chưa phải chứng nhận đã hiểu.</p>`;
 }
 const title=p.source==='game-local'?'Vị trí cần xem lại':session.related?'Thử sức ở thế cờ mới':'Quan sát và đưa ra ý tưởng';
 const shown=after&&session.stage!=='retry'&&showVariation?pos.play(p.solution):pos;
 return `${heading(title,'Tự suy nghĩ trước, rồi đối chiếu với lời giải.','lessons')}<div class="learn-grid"><div class="board-panel"><div class="board-meta"><span class="player-pill"><i class="player-dot ${pos.turn==='b'?'black':''}"></i>${pos.turn==='w'?'Đỏ':'Đen'} đến lượt</span><span class="pill">${after?'Đang đối chiếu':'Chưa mở lời giải'}</span></div>${boardHTML(shown,{interactive:['reflect','retry'].includes(session.stage),chosen:selected,mark:after&&session.stage!=='retry'&&!showVariation?p.solution:null,last:showVariation?p.solution:null})}<p id="move-feedback" class="feedback" role="status"></p><p class="subtle">${p.source==='game-local'?'Từ ván của bạn · phân tích còn nông, cần kiểm chứng.':'Bài tự dựng · chưa được chuyên gia duyệt sư phạm.'}</p>${btn('Lưu chỗ này · về trang chủ','pause','','quiet')}<a class="quiet" href="#rules">Xem luật đi quân</a></div><section class="panel learning-panel"><div class="stepper"><span class="active"></span><span class="${after?'active':''}"></span><span></span></div>${right}<p id="learn-feedback" class="feedback" role="status"></p><small id="draft-status">Đã lưu trên trình duyệt này</small></section></div>`;
}
function finish(){const s=state.session,p=currentPuzzle();state=CC.finishPuzzle(state,s,p,{success:accepted(p,s.candidate),assisted:s.assisted});save();if(s.related)go('summary');else nextRelated();}
function nextRelated(){const s=state.session,p=currentPuzzle(),r=CC.recommend(FIXTURES,state.records,p.skill,p.id);if(!r)return go('summary');state.session={...s,stage:'related_pending',pendingPuzzleId:r.puzzle.id};save();render();}
function lessons(){const opening=lessonPhase==='opening';return `${heading('Bài học','Học một ý tưởng, rồi đặt nó vào một thế cờ cụ thể.')}<div class="filters">${[['opening','Khai cuộc'],['middle','Trung cuộc'],['end','Tàn cuộc']].map(([v,t])=>btn(t,'phase',v,lessonPhase===v?'active':'')).join('')}</div>${opening?`<p class="notice">Bốn minh họa nước mở đầu. Đây chưa phải giáo trình khai cuộc hoặc thư viện biến đầy đủ.</p><div class="list">${OPENINGS.map((p,i)=>`<div class="list-row"><div class="row-main"><span class="mini-icon">${p.icon}</span><div><h3>${p.title}</h3><p>${p.short}</p></div></div>${btn('Xem hướng dẫn →','opening',String(i),'secondary')}</div>`).join('')}</div>`:`<p class="notice">${lessonPhase==='end'?'12 thế ít quân với mục tiêu ngắn; chưa có bộ tàn cuộc chuẩn hoặc yêu cầu đánh đến hết ván.':'Luyện bốn kỹ năng thường cần khi phân tích trung cuộc. Các hình mẫu đã giản lược quân, không phải ván trung cuộc đầy đủ.'}</p><div class="grid-2">${Object.entries(SKILLS).map(([k,n])=>`<section class="panel"><p class="eyebrow">${FIXTURES.filter(p=>p.skill===k).length} HÌNH MẪU</p><h3>${n}</h3><p class="subtle">${HOW[k]}</p><div class="list">${FIXTURES.filter(p=>p.skill===k).map(p=>`<div class="list-row"><div><h3>${esc(p.title)}</h3><p>${state.records[p.id]?.completedAt?'Đã hoàn thành · '+date(state.records[p.id].completedAt):state.records[p.id]?.seenCount?'Đã mở · có thể luyện lại':'Chưa gặp trên thiết bị này'}</p></div>${btn('Luyện','start',p.id,'secondary')}</div>`).join('')}</div></section>`).join('')}</div>`}`;}
const OPENINGS=[{title:'Pháo đầu',icon:'炮',short:'Quan sát Pháo trên lộ giữa',move:'h2e2',text:'Pháo từ h2 sang e2, đi ngang trên đường không bị cản. Đây là cách đưa Pháo vào lộ giữa. Tiếp theo vẫn cần phát triển quân và kiểm tra phản ứng đối thủ; không có một chuỗi nước bắt buộc cho mọi ván.'},{title:'Phi tượng',icon:'相',short:'Nhìn cách Tượng phối hợp phòng thủ',move:'g0e2',text:'Tượng từ g0 lên e2; mắt Tượng f1 phải trống. Tượng hoạt động ở bên mình và không qua sông. Một nước phát triển Tượng chưa đủ để khẳng định bên nào hơn.'},{title:'Tiên nhân chỉ lộ',icon:'兵',short:'Quan sát nước tiến Tốt mở đầu',move:'c3c4',text:'Tốt từ c3 tiến lên c4. Khi chưa qua sông, Tốt chỉ đi thẳng một ô. Hãy quan sát những đường quân khác có thể hoạt động sau khi Tốt tiến.'},{title:'Sĩ giác pháo',icon:'炮',short:'Một cách bố trí Pháo khác',move:'h2f2',text:'Pháo từ h2 sang f2, không cần quân ngòi khi không ăn quân. Tên khai cuộc chỉ mô tả cách bố trí ban đầu; kế hoạch tiếp theo phụ thuộc nước đáp của đối thủ.'}];
function opening(i){const p=OPENINGS[i]||OPENINGS[0],pos=XQ.Position.fromFen(XQ.START_FEN),after=replayIndex>0?pos.play(p.move):pos;return `${heading(p.title,'Minh họa khai cuộc · đã xem không đồng nghĩa đã hiểu','lessons')}<div class="learn-grid"><div class="board-panel">${boardHTML(after,{last:replayIndex?p.move:null})}<div class="button-row">${btn('← Thế ban đầu','opening-before',i,'secondary')}${btn('Xem nước đi →','opening-after',i,'secondary')}</div></div><div class="panel"><p class="eyebrow">HƯỚNG DẪN NGẮN</p><h2>${p.short}</h2><p>${p.text}</p><p class="notice">Nước minh họa được kiểm tra bằng bộ luật. Chưa có câu hỏi và chấm hiểu biết cho phần khai cuộc này.</p><a class="primary" href="#lessons">Trở lại bài học →</a></div></div>`;}
function playSetup(){const g=activeGame();return `${heading('Chọn một ván cờ','Chơi tập trung, rồi cùng nhìn lại sau ván.')}<div class="grid-3">${[['bot','車','Chơi với máy','Máy nhẹ trên thiết bị · chưa có Elo'],['local','棋','Hai người một máy','Luân phiên cầm Đỏ và Đen'],['online','↗','Chơi trực tuyến','Sẽ phát triển sau vòng học cốt lõi']].map(([id,ic,t,d])=>`<button class="mode-card ${mode===id?'active':''}" data-action="mode" data-value="${id}" ${id==='online'?'disabled':''}><span class="mode-icon">${ic}</span><b>${t}</b><span>${d}</span></button>`).join('')}</div><div class="grid-2 separation"><section class="panel"><h3>Thiết lập trước khi chơi</h3>${g?`<p class="notice">Mỗi lần chỉ có một ván. Đồng hồ vẫn chạy khi bạn rời trang.</p><a class="primary" href="#game/${g.id}">Tiếp tục ván đang chơi →</a>`:`<form id="new-game-form"><label class="field"><span>Bên bạn cầm</span><select name="color"><option value="w">Đỏ · đi trước</option><option value="b">Đen · đi sau</option><option value="random">Ngẫu nhiên</option></select></label><label class="field"><span>Thời gian mỗi bên và giây cộng sau mỗi nước</span><select name="time"><option value="600+5">10 phút + 5 giây</option><option value="300+3">5 phút + 3 giây</option><option value="180+2">3 phút + 2 giây</option><option value="0+0">Không giới hạn thời gian</option></select></label>${mode==='bot'?'<label class="field"><span>Mức tìm kiếm của máy</span><select name="depth"><option value="1">Nhanh · 1 nửa nước</option><option value="2">Kỹ hơn · tối đa 2 nửa nước</option></select></label>':''}<button class="primary full" type="submit">Bắt đầu chơi →</button></form>`}<p class="subtle separation">Không gợi nước hoặc xem lại lịch sử bàn cờ khi ván đang chạy. <a href="#rules">Xem phạm vi bộ luật</a>.</p></section><section class="panel"><h3>Nhập ván để xem lại</h3><p class="subtle">Dán ký phổ Việt hoặc nước tọa độ. Hệ thống dừng tại nước lỗi và không lưu ván dở do nhập lỗi. Chưa nhận dạng ảnh.</p><form id="import-form"><label class="field"><span>FEN ban đầu · có thể để trống</span><textarea name="fen" rows="2" maxlength="200" placeholder="Để trống nếu bắt đầu từ thế xuất phát"></textarea></label><label class="field"><span>Biên bản</span><textarea name="moves" rows="4" maxlength="10000" placeholder="P2-5 M8.7 hoặc h2e2 h9g7"></textarea></label><label class="field"><span>Hoặc mở file văn bản .txt</span><input type="file" id="notation-file" accept=".txt,text/plain"></label><label class="field"><span>Bên cần xem lại</span><select name="reviewSide"><option value="w">Đỏ</option><option value="b">Đen</option></select></label><button class="secondary" type="submit">Kiểm tra & mở ván</button><p id="import-feedback" class="feedback" role="status"></p></form></section></div>`;}
function gameList(){const filtered=state.games.slice().reverse().filter(g=>libraryFilter==='all'||libraryFilter==='favorite'&&g.favorite||libraryFilter==='unreviewed'&&!g.moments||libraryFilter==='reviewed'&&g.moments);const pages=Math.ceil(filtered.length/20);libraryPage=Math.min(libraryPage,Math.max(0,pages-1));return `<div class="filters">${[['all','Tất cả'],['unreviewed','Chưa xem lại'],['reviewed','Đã phân tích'],['favorite','Yêu thích']].map(([k,v])=>btn(v,'library-filter',k,k===libraryFilter?'active':'')).join('')}</div><div class="list">${filtered.slice(libraryPage*20,libraryPage*20+20).map(g=>`<div class="list-row"><div><h3>${esc(g.title)}</h3><p>${date(g.createdAt)} · ${g.player==='b'?'Cầm Đen':'Cầm Đỏ'} · ${g.moves?.length||0} nửa nước</p><p>${esc(g.status?.reason||'Đang chơi')} · ${g.moments?'Đã phân tích':'Chưa phân tích'}</p></div><div class="button-row">${btn(g.favorite?'★':'☆','favorite',g.id,'quiet')}<a class="secondary" href="#${g.status?.over?'moments':'game'}/${g.id}">${g.status?.over?'Xem lại':'Tiếp tục'} →</a></div></div>`).join('')||'<p>Chưa có ván phù hợp bộ lọc.</p>'}</div>${pages>1?`<div class="button-row">${btn('Trang trước','library-prev','','secondary')}<span>${libraryPage+1} / ${pages}</span>${btn('Trang sau','library-next','','secondary')}</div>`:''}`;}
function newGame({fen=XQ.START_FEN,moves=[],imported=false,color='w',seconds=0,increment=0,depth=1}={}){
 if(activeGame())return toast('Kết thúc ván đang chơi trước khi tạo ván khác.');
 let pos=XQ.Position.fromFen(fen),history=[];fen=pos.fen();
 if(imported&&state.games.some(g=>g.initialFen===fen&&JSON.stringify(g.moves.map(m=>m.move))===JSON.stringify(moves)))return toast('Ván hoặc thế cờ này đã có trong Ván của tôi.');
 for(const move of moves){const next=pos.play(move);history.push({move,before:pos.fen(),after:next.fen(),side:pos.turn});pos=next;}
 if(color==='random')color=Math.random()<.5?'w':'b';
 const g={id:'g'+Date.now(),title:imported?'Ván / thế cờ đã nhập':mode==='bot'?'Ván với máy':'Ván hai người một máy',createdAt:Date.now(),mode:imported?'import':mode,player:color,depth,initialFen:fen,fen:pos.fen(),moves:history,status:imported?{over:true,winner:null,reason:'Đã nhập để học'}:pos.status(),clock:{w:seconds*1000,b:seconds*1000,last:Date.now(),enabled:seconds>0,increment:increment*1000},invalidMoves:[]};
 state.games.push(g);state.games=state.games.slice(-200);save();selected=null;boardFlipped=color==='b';go((imported?'moments/':'game/')+g.id);if(!imported)maybeBot(g);
}
function notationTable(g,clickable=false){const rows=CC.pairMoveHistory(g.initialFen,g.moves.map(m=>m.move));return `<div class="notation-scroll"><table class="notation-table"><thead><tr><th>Nước</th><th>Đỏ</th><th>Đen</th></tr></thead><tbody>${rows.slice(clickable?0:-10).map(row=>`<tr><td>${row.number}</td>${['red','black'].map(side=>`<td>${row[side]?clickable?btn(esc(row[side].notation),'replay-jump',String(row[side].ply+1),'quiet'):esc(row[side].notation):'—'}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="3">Chưa có nước đi</td></tr>'}</tbody></table></div>`;}
function captures(g){const lost={w:[],b:[]};for(const m of g.moves){const before=XQ.Position.fromFen(m.before),piece=before.board[XQ.index(m.move.slice(2))];if(piece!=='.')lost[XQ.side(piece)].push(piece);}return `<div class="captures"><p>Đỏ đã mất: ${lost.w.map(p=>prefs.pieces==='vi'?NAMES[p.toLowerCase()]:HAN[p]).join(' · ')||'—'}</p><p>Đen đã mất: ${lost.b.map(p=>prefs.pieces==='vi'?NAMES[p.toLowerCase()]:HAN[p]).join(' · ')||'—'}</p></div>`;}
function gameView(g){
 if(!g)return empty('Không tìm thấy ván','Bạn có thể bắt đầu một ván mới.','play','Chơi cờ');
 const pos=XQ.Position.fromFen(g.fen),last=g.moves.at(-1)?.move,top=boardFlipped?'w':'b',bottom=XQ.other(top),player=color=>`<span class="player-pill"><i class="player-dot ${color==='b'?'black':''}"></i>${color==='w'?'Đỏ':'Đen'}</span><span id="clock-${color}" class="clock ${pos.turn===color?'active':''}">${clockText(g,color)}</span>`;
 return `${heading(g.title,'Tập trung vào ván cờ. Phần học mở sau khi kết thúc.','play')}<div class="learn-grid"><div class="board-panel"><div class="board-meta">${player(top)}</div>${boardHTML(pos,{interactive:!g.status.over&&!busy&&(g.mode==='local'||pos.turn===g.player),chosen:selected,last})}<div class="board-meta">${player(bottom)}</div><p id="game-feedback" class="feedback" role="status"></p>${captures(g)}</div><div class="panel game-panel">${g.status.over?`<div class="game-result"><h2>${g.status.winner?(g.status.winner==='w'?'Đỏ':'Đen')+' thắng':g.status.needsVerification?'Cần kiểm chứng phán quyết':'Ván đã kết thúc'}</h2><p>${esc(g.status.reason)}</p><a class="primary" href="#moments/${g.id}">Xem lại ván này →</a><div class="button-row">${btn('Chơi ván tiếp','rematch',g.id,'secondary')}</div></div>`:`<p class="eyebrow">${busy?'MÁY ĐANG TÍNH NƯỚC':'VÁN ĐANG DIỄN RA'}</p><h2>${pos.turn==='w'?'Đỏ':'Đen'} đến lượt${pos.inCheck()?' · bị chiếu':''}</h2><p class="subtle">${g.mode==='bot'?'Máy tìm kiếm tối đa '+g.depth+' nửa nước · chưa xếp hạng.':'Hai người thao tác trên cùng thiết bị.'}</p>`}<h3>Biên bản</h3>${notationTable(g)}${!g.status.over?`<div class="button-row">${btn('Xin thua','resign',g.id,'secondary')}${g.mode==='local'?btn('Thỏa thuận hòa','draw',g.id,'quiet'):''}</div>`:''}<details class="separation"><summary>Luật và giới hạn</summary><p>Không đi lại nước và không mở phân tích trong ván. Những chuỗi lặp cần phân xử ngoài phạm vi đã kiểm chứng sẽ dừng để xác minh, không tự gán thắng hoặc hòa.</p><a href="#rules">Đọc phạm vi bộ luật</a></details></div></div>`;
}
function clockText(g,color){if(!g.clock?.enabled)return '∞';let ms=g.clock[color];if(!g.status.over&&XQ.Position.fromFen(g.fen).turn===color)ms-=Date.now()-g.clock.last;ms=Math.max(0,ms);return Math.floor(ms/60000)+':'+String(Math.floor(ms/1000)%60).padStart(2,'0');}
function tickGame(g){if(!g||g.status.over||!g.clock?.enabled)return false;const pos=XQ.Position.fromFen(g.fen);if(g.clock[pos.turn]-(Date.now()-g.clock.last)<=0){g.clock[pos.turn]=0;g.status={over:true,winner:XQ.other(pos.turn),reason:'Hết thời gian'};save();return true;}return false;}
function moveGame(g,move){if(tickGame(g)||g.status.over)return render();const pos=XQ.Position.fromFen(g.fen),next=pos.play(move),captured=pos.board[XQ.index(move.slice(2))]!=='.';const clock=CC.applyClockMove(g.clock,pos.turn,Date.now());if(clock.expired){tickGame(g);return render();}g.clock=clock.clock;g.moves.push({move,before:pos.fen(),after:next.fen(),side:pos.turn});g.fen=next.fen();g.status=next.status();if(!g.status.over){const repetition=CC.repetitionStatus(g.initialFen,g.moves.map(m=>m.move));if(repetition.over||repetition.needsVerification)g.status={...repetition,over:true};}if(!g.status.over&&g.moves.length>=200)g.status={over:true,winner:null,reason:'Giới hạn 200 nửa nước của bản thử · không tính hòa',needsVerification:true};selected=null;playSound(next.inCheck()?'check':captured?'capture':'move');save();render();maybeBot(g);}
function maybeBot(g){if(busy||!g||g.mode!=='bot'||g.status.over||XQ.Position.fromFen(g.fen).turn===g.player)return;busy=true;if(route()[0]==='game')render();setTimeout(()=>{try{if(tickGame(g)||g.status.over)return;const pos=XQ.Position.fromFen(g.fen),a=XQ.analyze(pos,{depth:g.depth,maxMs:g.depth===2?550:180});busy=false;if(a.bestMove)moveGame(g,a.bestMove);}catch{toast('Máy chưa xử lý được. Hãy thử mở lại ván.');}finally{busy=false;if(route()[0]==='game')render();}},100);}
function inferSkill(pos,move){if(pos.inCheck())return 'safety';return({c:'cannon',h:'horse'})[pos.board[XQ.index(move.slice(0,2))].toLowerCase()]||'material';}
async function analyzeGame(g){if(g.moments)return render();if(busy)return;busy=true;render();try{let turns=g.moves.map((m,i)=>({...m,ply:i})).filter(m=>g.mode==='local'||m.side===g.player).slice(-16);if(!turns.length&&g.mode==='import'&&!g.moves.length)turns=[{before:g.initialFen,move:null,ply:0}];const found=[];for(let n=0;n<turns.length;n++){analysisProgress=`Đang kiểm tra vị trí ${n+1} / ${turns.length}`;if($('analysis-progress'))$('analysis-progress').textContent=analysisProgress;const m=turns[n],pos=XQ.Position.fromFen(m.before),a=XQ.analyze(pos,{depth:2,maxMs:180});if(!a.bestMove||!a.ranked.length)continue;const actual=a.ranked.find(x=>x.move===m.move),best=a.ranked[0],loss=actual?best.score-actual.score:0,skill=inferSkill(pos,m.move||best.move);if(m.move&&(!actual||loss<80||a.depth<1))continue;let pvPos=pos;const line=best.pv.map(v=>{const d=XQ.describe(pvPos,v);pvPos=pvPos.play(v);return d;}).join('; sau đó ');found.push({id:g.id+'-p'+m.ply,title:'Vị trí ở nửa nước '+(m.ply+1),fen:pos.fen(),solution:best.move,alternatives:a.ranked.filter(x=>best.score-x.score<=35).map(x=>x.move),skill,source:'game-local',gameId:g.id,ply:m.ply,loss,what:m.move?`Trong ván bạn đã đi ${XQ.describe(pos,m.move)}. Tìm kiếm local sâu ${a.depth} nửa nước xếp nước này thấp hơn lựa chọn dẫn đầu ${loss} điểm quy ước.`:`Một nước được máy local đề xuất: ${XQ.describe(pos,best.move)}.`,why:`Dòng tìm kiếm hợp lệ: ${line}. Điểm chỉ dựa trên vật chất và Tốt qua sông. Đây không phải biến bắt buộc hoặc kết luận tốt nhất toàn cục.`,how:HOW[skill]});await new Promise(r=>setTimeout(r,0));}g.moments=found.sort((a,b)=>b.loss-a.loss).slice(0,3).sort((a,b)=>a.ply-b.ply);save();}catch{toast('Chưa phân tích được ván. Dữ liệu ván vẫn được giữ.');}finally{busy=false;render();}}
function moments(g){if(!g)return empty('Chưa có ván để xem lại','Chơi hoặc nhập một ván trước.','play','Mở trang chơi');if(!g.status.over)return empty('Ván đang diễn ra','Kết thúc ván rồi mở phần phân tích.','game/'+g.id,'Tiếp tục ván');return `${heading('Những điểm đáng nhìn lại','Chọn một hình để tự đánh giá trước khi xem phương án.','mistakes')}<p class="notice">Gợi ý bằng máy local tìm kiếm nông; nhãn kỹ năng và mức chênh lệch chưa phải kết luận lỗi tư duy. Phân tích tối đa 16 lượt gần nhất, đề xuất tối đa 3 vị trí.</p>${g.moments?g.moments.length?'<div class="list">'+g.moments.map((p,i)=>`<div class="list-row"><div class="row-main"><span class="mini-icon">0${i+1}</span><div><h3>${esc(p.title)}</h3><p>${state.records[p.id]?.completedAt?'Đã học · '+date(state.records[p.id].completedAt):'Tự quan sát trước · khoảng 3–5 phút'}</p></div></div>${btn('Suy nghĩ ở đây →','start',p.id,'secondary')}</div>`).join('')+'</div>':empty('Chưa thấy sai sót rõ trong phạm vi đã kiểm tra','Bạn đã giữ được các quyết định khá ổn theo tìm kiếm nông. Điều này chưa có nghĩa toàn ván hoàn hảo.'):`<div class="panel empty">${busy?`<span class="spinner"></span><p id="analysis-progress">${esc(analysisProgress||'Đang kiểm tra các nước hợp lệ…')}</p>`:btn('Tìm điểm cần học →','analyze',g.id)}</div>`}<div class="button-row"><a class="secondary" href="#replay/${g.id}">Xem lại toàn ván</a><a class="quiet" href="#play">Chơi ván khác</a></div>`;}
function replay(g){if(!g)return empty('Không tìm thấy ván','Mở lại từ danh sách ván.','mistakes');replayIndex=Math.max(0,Math.min(replayIndex,g.moves.length));const fen=replayIndex?g.moves[replayIndex-1].after:g.initialFen;return `${heading('Xem lại toàn ván','Chế độ xem tự do. Khi luyện một điểm, các nước sau sẽ được giấu.','moments/'+g.id)}<div class="learn-grid"><div class="board-panel">${boardHTML(XQ.Position.fromFen(fen),{last:replayIndex?g.moves[replayIndex-1].move:null})}<div class="button-row">${btn('← Trước','replay-prev',g.id,'secondary')}<span class="pill">${replayIndex} / ${g.moves.length}</span>${btn('Sau →','replay-next',g.id,'secondary')}</div></div><div class="panel"><h3>${esc(g.title)}</h3><p>${replayIndex?esc(XQ.describe(XQ.Position.fromFen(g.moves[replayIndex-1].before),g.moves[replayIndex-1].move)):'Thế cờ ban đầu'}</p>${notationTable(g,true)}<div class="button-row"><a class="primary" href="#moments/${g.id}">Chọn điểm để học →</a>${btn('Xuất biên bản','export-game',g.id,'secondary')}${btn('Xóa ván','delete-game',g.id,'danger')}</div></div></div>`;}
function mistakes(){return heading('Ván của tôi','Ván cá nhân và những vị trí bạn muốn hiểu rõ hơn.')+(state.games.length?gameList():empty('Bắt đầu từ một ván của bạn','Sau ván, hệ thống gợi ý những điểm để nhìn lại.','play','Chơi hoặc nhập ván'))+`<p class="subtle separation">“Ôn tập” là lịch luyện đến hạn; khu vực này là nơi tìm lại các ván. Hai nơi dùng chung kết quả học.</p>`;}
function reviews(){const rows=Object.values(state.records).filter(r=>r.dueAt).sort((a,b)=>Date.parse(a.dueAt)-Date.parse(b.dueAt)),s=state.session;return `${heading('Ôn tập','Một hình mỗi lần. Tiến độ bắt đầu từ lúc bạn thực sự hoàn thành.')} ${s&&s.stage!=='summary'?`<div class="next-up"><div><strong>Có một bài đang dở</strong><p>Tiếp tục đúng bước và giữ câu trả lời đã nhập.</p></div>${btn('Tiếp tục →','resume')}</div>`:''}<div class="button-row"><a class="secondary" href="#profile">Xem tiến độ</a></div>${rows.length?'<div class="list">'+rows.map(r=>{const p=findPuzzle(r.puzzleId);if(!p)return '';return `<div class="list-row"><div><h3>${esc(p.title)}</h3><p>${r.assisted||!r.lastSuccess?'Cần luyện thêm · ':'Đã làm · '}${Date.parse(r.dueAt)<Date.now()-86400000?'Quá hạn · ':''}${Date.parse(r.dueAt)<=Date.now()?'Đã đến hạn':'Hẹn '+date(r.dueAt)}</p></div>${btn('Ôn hình này','start-review',p.id,'secondary')}</div>`;}).join('')+'</div>':empty('Chưa có hình đến lịch ôn','Hoàn thành một hình, lịch ôn sẽ được tạo tự động.')}<p class="notice separation">Quy tắc thử nghiệm: 1 / 2 / 7 / 14 / 30 ngày, tùy kết quả và hỗ trợ. Chưa có email, thông báo đẩy hoặc “giờ học tối ưu”.</p>`;}
function summary(){if(!state.session)return empty('Chưa có phiên học','Hãy chọn một bài để bắt đầu.');return `${heading('Khép lại một phiên học','Ghi một điều nhỏ để lần sau biết mình cần tiếp tục ở đâu.')}<section class="panel summary-box"><span class="summary-icon">✓</span><h2>Hôm nay bạn mang theo điều gì?</h2><form id="summary-form">${['Tôi đã quan sát trước khi chọn nước','Tôi hiểu thêm lý do của một nước đi','Tôi đã thử một hình cùng chủ đề','Tôi còn điều chưa chắc và muốn ôn lại'].map((x,i)=>`<label class="check-line"><input type="checkbox" name="check" value="${i}" ${(state.session.summaryChecks||[]).includes(String(i))?'checked':''}><span>${x}</span></label>`).join('')}<label class="field"><span>Một điều bạn muốn nhớ</span><textarea name="note" maxlength="1500" rows="3" placeholder="Lần sau tôi sẽ kiểm tra…">${esc(state.session.summaryNote||'')}</textarea></label><p class="notice">Đây là tự đánh giá. Các ô tích không tự tăng trình độ hoặc thay đổi lịch ôn. Mỗi hình đã có lịch riêng từ lúc hoàn thành.</p><button class="primary" type="submit">Lưu & trở về trang chủ →</button></form></section>`;}

function profile(){const records=completed(),stats=CC.evidence(state.records);return `${heading('Tiến độ của bạn','Chỉ ghi nhận hoạt động thực tế trên trình duyệt này.')}<div class="stat-grid"><div class="stat"><b>${stats.count}</b><span>lượt luyện đã kết thúc</span></div><div class="stat"><b>${dueRecords().length}</b><span>hình đến hạn ôn</span></div><div class="stat"><b>${stats.firstEligible?Math.round(stats.firstCorrect/stats.firstCount*100)+'%':'—'}</b><span>${stats.firstEligible?`nước đầu phù hợp mẫu, không hỗ trợ · ${stats.firstCorrect}/${stats.firstCount} bài`:'Chưa đủ dữ liệu · cần 6 bài khác nhau để hiện tỷ lệ'}</span></div></div><p class="notice">Trình độ tự chọn: ${prefs.level==='new'?'Chưa biết chơi':prefs.level==='beginner'?'Mới biết luật':'Đã biết chơi'}. Đây không phải kết quả đánh giá đầu vào hoặc xếp hạng thi đấu.</p><div class="grid-2"><section class="panel"><h3>Bằng chứng theo kỹ năng</h3>${Object.entries(SKILLS).map(([k,n])=>{const e=CC.evidence(state.records,k);return `<div class="skill-row"><h4>${n}</h4><p>${e.eligible?`${e.count} lượt · ${e.independent} lượt chọn nước phù hợp không hỗ trợ · ${e.assisted} lượt có hỗ trợ`:`Chưa đủ dữ liệu (${e.count}/6 lượt). Chưa hiện biểu đồ hoặc điểm kỹ năng.`}</p>${e.eligible?`<progress max="${e.count}" value="${e.independent}" aria-label="Lượt chọn nước phù hợp không hỗ trợ"></progress>`:''}</div>`;}).join('')}<p class="subtle">Kết quả nước đi không chứng minh chất lượng lý giải hoặc mức thành thạo.</p><a class="secondary" href="#review">Đến lịch ôn →</a></section><section class="panel"><h3>Góc cá nhân</h3><form id="profile-form"><label class="field"><span>Tên hiển thị</span><input type="text" name="name" maxlength="40" value="${esc(state.profile.name)}" placeholder="Bạn muốn được gọi là gì?"></label><button class="secondary" type="submit">Lưu tên</button></form><p class="subtle separation">Hồ sơ trên trình duyệt, chưa có tài khoản đồng bộ. Đổi thiết bị không tự mang theo tiến độ.</p><a class="secondary" href="#settings">Giao diện và dữ liệu →</a></section></div><section class="panel separation"><h3>Những lần tự nhìn lại</h3>${state.summaries.length?state.summaries.slice(-5).reverse().map(item=>`<div class="explanation-section"><h4>${date(item.at)}</h4><p>${esc(item.note||'Đã lưu tự đánh giá.')} (${item.checks.length} mục)</p></div>`).join(''):'<p>Chưa có tự đánh giá. Sau phiên học, bạn có thể ghi một điều muốn nhớ.</p>'}</section>`;}
function about(){return `${heading('Về Cờ Chill','Một bản thử để kiểm tra cách chơi và học trước khi hoàn thiện sản phẩm.')}<article class="article"><h2>Bạn có thể làm gì?</h2><p>Chơi với máy local hoặc hai người một máy, nhập FEN và nước tọa độ, xem lại ván, trả lời trước lời giải, luyện hình cùng chủ đề, lưu bài dở, ôn theo lịch và tự đánh giá cuối phiên.</p><h2>Điều gì đang chạy thật?</h2><p>Luật bảy quân, kiểm tra an toàn Tướng, chiếu hết/hết nước, máy tìm kiếm vật chất tối đa hai nửa nước, 12 thế cờ tự dựng, lưu dữ liệu trình duyệt và lịch ôn theo quy tắc cố định.</p><h2>Điều gì chưa có?</h2><p>Chưa có Pikafish hoặc engine mạnh, LLM chấm lập luận, ML đã huấn luyện, PvP online, bạn bè/chat, tài khoản nhiều thiết bị, thông báo đẩy, kho dữ liệu lớn hoặc giáo trình đã được chuyên gia duyệt. Bộ luật chỉ xử lý được một số chuỗi lặp và chiếu liên tục rõ ràng; đuổi dai, chiếu đuổi hỗn hợp và phán quyết giải đấu vẫn cần kiểm chứng. Không có số liệu hiệu quả học tập được công bố.</p><h2>Dữ liệu thuộc về bạn</h2><p>Câu trả lời, ván cờ và tiến độ được lưu bằng localStorage trên trình duyệt này. Ứng dụng không gửi chúng đến máy chủ hoặc dùng để huấn luyện. Xóa dữ liệu trình duyệt sẽ mất tiến độ; hãy xuất JSON nếu muốn giữ bản sao. Dịch vụ hosting vẫn xử lý yêu cầu truy cập web thông thường.</p><h2>Bản thử và bản hoàn thiện</h2><p>Bản này dùng để thử những quyết định từ V4 và bản phác ngày 15/10. Đã cập nhật các lựa chọn trong UI/UX + Luật và UX35. Các mục chưa đủ điều kiện triển khai được ghi riêng trong bộ câu hỏi V5. Bạn không cần đổi ý định sản phẩm để khớp giới hạn của bản thử.</p><a class="primary" href="#home">Trở về Cờ Chill →</a></article>`;}

function applyPreferences(){document.documentElement.dataset.theme=prefs.theme;document.documentElement.dataset.font=prefs.font;document.body.classList.toggle('sidebar-collapsed',prefs.sidebar);$('sidebar-toggle')?.setAttribute('aria-expanded',String(!prefs.sidebar));$('sound-toggle')?.setAttribute('aria-pressed',String(prefs.sound));if($('sound-toggle'))$('sound-toggle').textContent=prefs.sound?'♪ Âm thanh bật':'♪ Âm thanh tắt';try{localStorage.setItem(PREF_KEY,JSON.stringify(prefs));}catch{toast('Không lưu được tùy chọn trên thiết bị.');}}
function playSound(kind){if(!prefs.sound)return;try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const now=audioContext.currentTime,o=audioContext.createOscillator(),gain=audioContext.createGain();o.type='sine';o.frequency.setValueAtTime(({move:420,capture:220,check:660,success:880,error:160})[kind]||420,now);gain.gain.setValueAtTime(0.001,now);gain.gain.exponentialRampToValueAtTime(.06,now+.02);gain.gain.exponentialRampToValueAtTime(.001,now+.2);o.connect(gain);gain.connect(audioContext.destination);o.start();o.stop(now+.22);}catch{/* Sound is optional; gameplay remains available. */}}
function settings(){const select=(key,label,options)=>`<label class="field"><span>${label}</span><select name="${key}" aria-label="${label}">${options.map(([v,t])=>`<option value="${v}" ${prefs[key]===v?'selected':''}>${t}</option>`).join('')}</select></label>`;return `${heading('Cài đặt','Chọn cách hiển thị thoải mái cho bạn.')}<div class="settings-grid grid-2"><section class="panel"><h3>Giao diện và bàn cờ</h3><form id="settings-form">${select('theme','Chủ đề',[['warm','Sáng ấm'],['cool','Trắng lạnh'],['dark','Tối']])}${select('pieces','Tên quân',[['han','Chữ Hán'],['vi','Tiếng Việt']])}${select('font','Cỡ chữ',[['normal','Dễ đọc'],['large','Lớn hơn']])}${select('level','Mức tự chọn',[['new','Chưa biết chơi'],['beginner','Mới biết luật'],['intermediate','Đã biết chơi']])}${select('tone','Giọng hướng dẫn',[['neutral','Trung tính'],['friendly','Bạn học cùng']])}<label class="check-line"><input type="checkbox" name="sound" ${prefs.sound?'checked':''}> Bật âm thanh nhẹ</label><button class="primary" type="submit">Lưu tùy chọn</button></form><p class="subtle separation">Âm thanh được tổng hợp trên thiết bị. Không sử dụng âm thanh từ ứng dụng khác.</p></section><section class="panel"><h3>Dữ liệu và quyền riêng tư</h3><p>Phiên học được lưu trên trình duyệt này. Chưa có tài khoản, lưu máy chủ hoặc đồng bộ thiết bị.</p><p>Không gửi ván hoặc câu trả lời để huấn luyện. Bản xuất không chứa đáp án ẩn của bài tập.</p><div class="button-row">${btn('Xuất dữ liệu cá nhân','export','','secondary')}${btn('Xóa lịch sử học và lịch ôn','delete-learning','','danger')}${btn('Xóa toàn bộ dữ liệu','delete','','danger')}</div><p class="subtle separation">File xuất là bản sao để đọc; chưa có nhập phục hồi tự động. Xóa dữ liệu không thể hoàn tác.</p><a href="#profile" class="secondary">Quay về hồ sơ →</a></section></div>`;}
function howto(){return `${heading('Bắt đầu với Cờ Chill','Một ván cờ, một điều hiểu rõ hơn.')}<div class="grid-2"><section class="panel"><h2>Bạn đang ở đâu?</h2><p>Chọn để điều chỉnh mức gợi mở. Đây là thông tin tự khai, chưa phải bài kiểm tra xếp hạng.</p><div class="button-row">${btn('Tôi chưa biết chơi','onboard','new','secondary')}${btn('Tôi mới biết luật','onboard','beginner','secondary')}${btn('Tôi đã biết chơi','onboard','intermediate','secondary')}</div><p class="subtle separation">Không cần nhập tuổi hoặc thông tin liên hệ để thử. Bản này lưu trên cùng trình duyệt.</p></section><section class="panel"><h3>Cách thao tác</h3><ol><li>Bấm một quân, rồi bấm ô muốn đi. Bấm lại quân đó để hủy chọn.</li><li>Sau ván, chọn một vị trí cần xem lại.</li><li>Viết suy nghĩ và chọn nước trước khi xem hướng dẫn.</li><li>Thử thêm một bài, rồi xem lịch ôn và ghi điều đã học.</li></ol><p>Nếu chưa tìm ra, dùng “Tôi chưa biết” để nhận câu hỏi quan sát nhỏ hơn.</p><div class="button-row">${btn('Thử một bài mẫu →','start',FIXTURES[0].id)}<a class="secondary" href="#play">Bỏ qua hướng dẫn · chơi cờ</a></div></section></div><p class="notice separation">Bài mẫu tự dựng, không phải ván của người dùng thật. Video hướng dẫn sẽ bổ sung sau; bản này có hướng dẫn chữ và bàn cờ tương tác.</p>`;}
function learningPath(){const stages=[['01','Nắm luật đi quân','Nhận ra đường đi và những điều kiện bị cản.','rules','Xem luật'],['02','Quan sát một hình cờ','Tự nêu ý trước khi xem hướng dẫn.','lessons','Chọn bài'],['03','Chơi và nhìn lại','Tìm một quyết định đáng học từ ván của bạn.','play','Chơi cờ'],['04','Vận dụng và ôn lại','Làm thêm bài rồi trở lại đúng lịch đã hẹn.','review','Mở lịch ôn']];return `${heading('Hành trình học','Bốn bước có thể quay lại bất cứ lúc nào.')}<div class="learning-path">${stages.map(([n,t,d,url,cta])=>`<article class="path-node panel"><span class="mini-icon">${n}</span><div><h2>${t}</h2><p>${d}</p><a class="secondary" href="#${url}">${cta} →</a></div></article>`).join('')}</div><p class="notice separation">Lộ trình gợi ý, chưa phải giáo trình phân cấp hoặc bài đánh giá đầu vào đã được kiểm chứng. Không khóa bài theo điểm kinh nghiệm giả.</p>`;}
function rulesPage(){const rules=[['Tướng','Đi thẳng hoặc ngang một ô trong cung. Hai Tướng không được nhìn thẳng nhau trên cùng cột khi không có quân chắn.'],['Sĩ','Đi chéo một ô và luôn ở trong cung.'],['Tượng','Đi chéo hai ô, không qua sông. Ô giữa đường chéo là mắt Tượng; có quân ở đó thì không đi được.'],['Mã','Đi một ô thẳng rồi một ô chéo ra ngoài. Ô thẳng đầu tiên là chân Mã; bị chặn thì không đi được hướng đó.'],['Xe','Đi thẳng hoặc ngang qua các ô trống; không nhảy qua quân.'],['Pháo','Khi không ăn quân, đi như Xe. Khi ăn quân, phải có đúng một quân nằm giữa Pháo và mục tiêu.'],['Tốt','Mỗi nước tiến một ô. Qua sông được đi ngang một ô; không bao giờ đi lùi.']];return `${heading('Luật đi quân','Tọa độ trên bàn không thay đổi khi lật góc nhìn.','howto')}<div class="grid-2">${rules.map(([n,t])=>`<section class="panel"><h3>${n}</h3><p>${t}</p></section>`).join('')}<section class="panel"><h3>An toàn Tướng và hết ván</h3><p>Không được đi nước khiến Tướng mình bị chiếu. Chiếu hết hoặc hết nước hợp lệ đều là thua. Hết giờ và xin thua được ghi riêng; thỏa thuận hòa cần hai người cùng đồng ý.</p></section></div><section class="panel separation"><h3>Lặp thế và phán quyết</h3><p>Đối chiếu WXF Rules 2018. Bản thử xử lý chuỗi chiếu một bên lặp rõ ràng; các chuỗi đuổi quân hoặc vừa chiếu vừa đuổi cần kiểm chứng. Chạm mốc lặp hoặc 100 nửa nước không ăn quân có thể dừng để xác minh; không tự suy thành hòa khi còn ngoại lệ.</p><p>Không dùng bản này làm trọng tài giải đấu. Các tình huống chưa rõ sẽ được bổ sung bằng case và nguồn luật cụ thể.</p><a class="secondary" href="https://www.wxf-xiangqi.org/images/wxf-rules/2018_World_XiangQi_Rules_English2018.pdf" target="_blank" rel="noopener">Nguồn WXF</a></section><div class="button-row">${state.session?btn('Trở lại bài đang học','resume'):btn('Thực hành một hình','start',FIXTURES[0].id)}<a class="quiet" href="#howto">Quay lại cách học</a></div>`;}
function render(){const [page,id]=route();let content;try{if(activeGame()&&['learn','opening','moments','replay','lessons','rules'].includes(page)){content=empty('Ván đang diễn ra','Hãy kết thúc ván trước khi mở hướng dẫn hoặc xem lại.','game/'+activeGame().id,'Tiếp tục ván');}else switch(page){case'play':content=playSetup();break;case'lessons':content=lessons();break;case'learn':content=learn();break;case'opening':content=opening(Number(id));break;case'game':content=gameView(state.games.find(g=>g.id===id));break;case'moments':content=moments(state.games.find(g=>g.id===id));break;case'replay':content=replay(state.games.find(g=>g.id===id));break;case'mistakes':content=mistakes();break;case'review':content=reviews();break;case'summary':content=summary();break;case'profile':content=profile();break;case'about':content=about();break;case'settings':content=settings();break;case'howto':content=howto();break;case'path':content=learningPath();break;case'rules':content=rulesPage();break;default:content=home();}}catch(e){content=empty('Không mở được dữ liệu này','Dữ liệu cũ vẫn được giữ. Bạn có thể xuất bản sao trong hồ sơ.','settings','Mở dữ liệu');console.error(e);} $('main').innerHTML=content;$('avatar').textContent=(state.profile.name||'C').slice(0,1).toUpperCase();document.querySelectorAll('.desktop-nav a,.mobile-nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));document.title=(document.querySelector('#main h1')?.textContent||'Trang chủ')+' · Cờ Chill';applyPreferences();}
function invalidMove(g,pos,move){const message=CC.illegalMoveReason(pos,move);if(g){g.invalidMoves=(g.invalidMoves||[]).concat({at:Date.now(),move,reason:message}).slice(-100);save();}const box=$('game-feedback')||$('move-feedback');if(box)box.textContent=message;playSound('error');toast(message);}
function selectSquare(sq){const [page,id]=route();if(page==='game'){const g=state.games.find(x=>x.id===id);if(!g||g.status.over||busy)return;const pos=XQ.Position.fromFen(g.fen);if(g.mode==='bot'&&pos.turn!==g.player)return;const piece=pos.board[XQ.index(sq)];if(piece!=='.'&&XQ.side(piece)===pos.turn){selected=selected===sq?null:sq;return render();}if(!selected)return toast('Chọn quân của bên đến lượt trước.');const move=selected+sq;if(!pos.legalMoves().includes(move))return invalidMove(g,pos,move);return moveGame(g,move);}
 if(page!=='learn'||!state.session)return;const session=state.session,p=currentPuzzle();if(!['reflect','retry'].includes(session.stage))return;const pos=XQ.Position.fromFen(p.fen),piece=pos.board[XQ.index(sq)];if(piece!=='.'&&XQ.side(piece)===pos.turn){selected=selected===sq?null:sq;session.selected=selected;save();return render();}if(!selected)return toast('Chọn quân của bên đến lượt trước.');const move=selected+sq;if(!pos.legalMoves().includes(move))return invalidMove(null,pos,move);selected=null;session.selected=null;if(session.stage==='retry'){session.retryCount=(session.retryCount||0)+1;if(accepted(p,move)){toast('Bạn đã đi lại được phương án. Lần đầu và lần luyện lại được ghi riêng.');playSound('success');session.stage='explain';}else if(session.retryCount>=3){session.stage='explain';toast('Đã thử ba lượt. Hãy đối chiếu ý tưởng và đưa hình này vào ôn tập.');}else{toast('Nước hợp lệ nhưng chưa khớp mục tiêu mẫu. Kiểm tra phản ứng của đối phương.');playSound('error');}}else session.candidate=move;save();render();}
function download(name,contents,type='application/json'){const url=URL.createObjectURL(new Blob([contents],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
